## Modified Zig client

```zig
const std = @import("std");
const rl = @import("raylib");
const net = std.net;
const posix = std.posix;
const mem = std.mem;

const ControllerEvents = enum(i16) {
    ANALOG_LX = 0,
    ANALOG_LY = 1,
    ANALOG_RX = 2,
    ANALOG_RY = 3,
    L1 = 4,
    L2 = 5,
    R1 = 6,
    R2 = 7,
    TRIANGLE = 8,
    CROSS = 9,
    SQUARE = 10,
    CIRCLE = 11,
    UP = 12,
    DOWN = 13,
    LEFT = 14,
    RIGHT = 15,
    SELECT = 16,
    START = 17,
};

// This must stay in the same order as the server's REGISTERED_EVENTS.
const EventMeta = struct {
    Type: u8,
    Code: u16,
};
const META: []const EventMeta = &._{
    .{ .Type=0, .Code=0x0a0 }, // EV_ABS / ABS_X
    .{ .Type=0, .Code=0x0a1 }, // EV_ABS / ABS_Y
    .{ .Type=0, .Code=0x0a3 }, // EV_ABS / ABS_RX
    .{ .Type=0, .Code=0x0a4 }, // EV_ABS / ABS_RY
    .{ .Type=1, .Code=0x004 }, // EV_KEY / BTN_TL
    .{ .Type=1, .Code=0x005 }, // EV_KEY / BTN_TL2
    .{ .Type=1, .Code=0x006 }, // EV_KEY / BTN_TR
    .{ .Type=1, .Code=0x007 }, // EV_KEY / BTN_TR2
    .{ .Type=1, .Code=0x008 }, // EV_KEY / BTN_NORTH
    .{ .Type=1, .Code=0x009 }, // EV_KEY / BTN_SOUTH
    .{ .Type=1, .Code=0x00A }, // EV_KEY / BTN_WEST
    .{ .Type=1, .Code=0x00B }, // EV_KEY / BTN_EAST
    .{ .Type=1, .Code=0x00C }, // EV_KEY / BTN_DPAD_UP
    .{ .Type=1, .Code=0x00D }, // EV_KEY / BTN_DPAD_DOWN
    .{ .Type=1, .Code=0x00E }, // EV_KEY / BTN_DPAD_LEFT
    .{ .Type=1, .Code=0x00F }, // EV_KEY / BTN_DPAD_RIGHT
    .{ .Type=1, .Code=0x010 }, // EV_KEY / BTN_SELECT
    .{ .Type=1, .Code=0x011 }, // EV_KEY / BTN_START
};

const EVENT_COUNT = META.len; // 18
const HEADER_SIZE = 2; // uint16 count
const PAYLOAD_PER_EVENT = 1 + 2 + 4; // uint8 + uint16 + int32
const PACKET_SIZE = HEADER_SIZE + EVENT_COUNT * PAYLOAD_PER_EVENT; // 128

/// Packs the current controller state into the fixed UDP packet.
fn packMessage(state: []const i32) []const u8 {
    var buf = [PACKET_SIZE]u8{0};
    var writer = std.io.fixedBufferWriter([PACKET_SIZE]u8){ &buf };
    writer.writeUint16(state.len, .little);
    for (META, 0..) |_, i| {
        writer.writeUint8(META[i].Type, .little);
        writer.writeUInt16(META[i].Code, .little);
        writer.writeInt32(state[i], .little);
    }
    return &buf[0..PACKET_SIZE];
}

fn sendToServer(sock: posix.fd_t, msg: []const u8) !void {
    var dest = try net.Address.parseIp4("127.0.0.1", 31415);
    const dest_addr = &dest.any;
    const dest_len: u32 = @intCast(dest.getOsSockLen());
    const ret = try posix.sendto(sock, msg.ptr, msg.len, dest_addr, dest_len);
    if (ret != msg.len) {
        std.log.warn("sendto returned {d}, expected {d}\n", .{ret, msg.len});
    }
}

fn initState() []const i32 {
    var s: [EVENT_COUNT + 1]i32 = undefined;
    @memset(s[0..EVENT_COUNT + 1], 0);
    return &s;
}

pub fn main() anyerror!void {
    const alloc = std.heap.page_allocator;
    _ = alloc;

    const screenWidth = 800;
    const screenHeight = 450;

    rl.initWindow(screenWidth, screenHeight, "raylib-zig example - keyboard to controller input");
    defer rl.closeWindow();

    rl.setTargetFPS(60);

    const state = initState();

    const sock = try posix.socket(posix.AF.INET, posix.SOCK.DGRAM, 0);
    defer posix.close(sock);

    while (!rl.windowShouldClose()) {
        // Update simulated controller inputs from keyboard
        state[@intFromEnum(rl.KeyboardKey.key_up)] = if (rl.isKeyDown(rl.KeyboardKey.key_up)) 1 else 0;
        state[@intFromEnum(rl.KeyboardKey.key_down)] = if (rl.isKeyDown(rl.KeyboardKey.key_down)) 1 else 0;
        state[@intFromEnum(rl.KeyboardKey.key_left)] = if (rl.isKeyDown(rl.KeyboardKey.key_left)) 1 else 0;
        state[@intFromEnum(rl.KeyboardKey.key_right)] = if (rl.isKeyDown(rl.KeyboardKey.key_right)) 1 else 0;

        // Send the entire controller state every frame using the shared format
        try sendToServer(sock, packMessage(state));

        rl.beginDrawing();
        rl.clearBackground(rl.Color.white);
        rl.drawText("Press arrow keys to simulate controller input!", 190, 200, 20, rl.Color.light_gray);
        rl.endDrawing();
    }
}
```

