## My answer to the prompt

Use one fixed packet format on both sides: 18 consecutive pairs, each containing a little-endian signed 16-bit event index and a little-endian signed 16-bit value. The packet is exactly 72 bytes. Explicit byte encoding avoids relying on host endianness or struct padding.

On the C server, replace the packet handling with byte-wise decoding:

```c
#define EVENT_COUNT (sizeof(REGISTERED_EVENTS) / sizeof(REGISTERED_EVENTS[0]))
#define PACKET_SIZE (EVENT_COUNT * 4)

static uint16_t read_le16(const unsigned char *p) {
    return (uint16_t)p[0] | ((uint16_t)p[1] << 8);
}

static int decode_i16_le(const unsigned char *p) {
    uint16_t u = read_le16(p);
    return u < 0x8000 ? (int)u : (int)u - 0x10000;
}

/* In the receive loop: */
unsigned char buffer[PACKET_SIZE];
ssize_t n = recvfrom(sockfd, buffer, sizeof buffer, 0,
                     (struct sockaddr *)&cli_addr, &cli_len);

if (n != PACKET_SIZE) {
    fprintf(stderr, "Expected %d bytes, got %zd\n", PACKET_SIZE, n);
    continue;
}

for (size_t i = 0; i < EVENT_COUNT; ++i) {
    const unsigned char *p = buffer + 4 * i;
    int index = decode_i16_le(p);
    int value = decode_i16_le(p + 2);

    if (index >= 0 && (size_t)index < EVENT_COUNT) {
        libevdev_uinput_write_event(controller,
            REGISTERED_EVENTS[index].type,
            REGISTERED_EVENTS[index].code, value);
