#define BUFFER_SIZE 256
#define PORT 31415
#define NUM_EVENTS 18

// Packet layout (little-endian):
// - 2 bytes: number of events in this packet (count)
// - for each event (same order as REGISTERED_EVENTS):
//   - 1 byte: event type (EV_ABS=0, EV_KEY=1)
//   - 2 bytes: event code
