        uint16_t cnt = get_le16((const uint8_t *)(buffer)); // copy to buffer? Wait tmp not buffer. Need put into buffer or parse directly.
        // Actually we need read into buffer to advance pointer. Use memcpy to buffer.
        memcpy(buffer, (const char *)tmp, (size_t)n);
        if ((uint16_t)n < (int)(sizeof(uint16_t)) || (uint16_t)(n - sizeof(uint16_t)) % PKT_PAYLOAD_SIZE != 0) {
            continue;
        }
        uint16_t cnt = get_le16(buffer);
        uint8_t *ptr = buffer + sizeof(uint16_t);

        for (uint16_t i = 0; i < cnt; ++i) {
            uint8_t etype;
            uint16_t ecode;
            int32_t value;
            memcpy(&etype, ptr, sizeof(etype));
            ptr += sizeof(etype);
            memcpy(&ecode, ptr, sizeof(ecode));
            ptr += sizeof(ecode);
            memcpy(&value, ptr, sizeof(value));
            ptr += sizeof(value);

            int idx = -1;
            for (int j = 0; j < (int)(sizeof(REGISTERED_EVENTS) / sizeof(REGISTERED_EVENTS[0])); ++j) {
                if (REGISTERED_EVENTS[j].type == (unsigned char)etype &&
                    REGISTERED_EVENTS[j].code == (unsigned int)ecode) {
                    idx = j;
                    break;
