const EVENT_COUNT = META.len; // 18
const HEADER_SIZE = 2; // uint16 little-endian count
const PAYLOAD_PER_EVENT = 1 + 2 + 4; // uint8 + uint16 + int32
const PACKET_SIZE = HEADER_SIZE + EVENT_COUNT * PAYLOAD_PER_EVENT; // 128

/// Packs the current controller state into the fixed UDP packet.
fn packMessage(state: []const i32) []const u8 {
    var buf = undefined;
    const len = PACKET_SIZE;
    var writer = std.io.fixedBufferWriter([]u8){ &buf[0..len] };
    writer.writeUint16(state.len, .little);
    for (META, 0..) |_, i| {
        writer.writeUint8(META[i].Type, .little);
        writer.writeUInt16(META[i].Code, .little);
        writer.writeInt32(state[i], .little);
    }
    return @truncate(buf[0..len]);
}

fn sendToServer(sock: posix.fd_t, msg: []const u8) !void {
    const dest = std.net.Address{};
    dest.ip4_addr = std.net.Ip4Address.fromOctets(.{0, 0, 1, 1});
    dest.port = 31415;
    const dest_addr = &dest.any;
    const dest_len: u32 = @intCast(dest.getOsSockLen());
    const ret = try posix.sendto(sock, msg.ptr, msg.len, dest_addr, dest_len);
    if (ret != msg.len) {
        std.log.warn("sendto returned {d}, expected {d}\n", .{ret, msg.len});
    }
}

fn initializeState() []const i32 {
    var s: [EVENT_COUNT + 1]i32 = undefined;
    @memset(s[0..EVENT_COUNT + 1], 0);
    return &s;
}

