    rl.initWindow(screenWidth, screenHeight, "raylib-zig example - keyboard to controller input");
    defer rl.closeWindow();

    rl.setTargetFPS(60);

    const state = initializeState();

    // Create UDP socket for sending packets
    const sock = try posix.socket(posix.AF.INET, posix.SOCK.DGRAM, 0);
    defer posix.close(sock);

    while (!rl.windowShouldClose()) {
        // Update state from keyboard
        state[@intFromEnum(rl.KeyboardKey.key_up)] = if (rl.isKeyDown(rl.KeyboardKey.key_up)) 1 else 0;
        state[@intFromEnum(rl.KeyboardKey.key_down)] = if (rl.isKeyDown(rl.KeyboardKey.key_down)) 1 else 0;
        state[@intFromEnum(rl.KeyboardKey.key_left)] = if (rl.isKeyDown(rl.KeyboardKey.key_left)) 1 else 0;
        state[@intFromEnum(rl.KeyboardKey.key_right)] = if (rl.isKeyDown(rl.KeyboardKey.key_right)) 1 else 0;

